def count_element_freq(t):
    freq = {}
    for element in t:
        if isinstance(element, tuple):
            sub_freq = count_element_freq(element)
            for key, value in sub_freq.items():
                freq[key] = freq.get(key, 0) + value
        else:
            freq[element] = freq.get(element, 0) + 1
    return freq
