def check_isosceles(a, b, c):
    # Check if it's a valid triangle
    if a + b <= c or a + c <= b or b + c <= a:
        return False

    # Check if all sides are different (scalene)
    if a != b and b != c and a != c:
        return True
    else:
        return False

