def lbs(arr):
    """
    Find the length of the longest bitonic subsequence in the given array.
    A bitonic sequence is one that first increases and then decreases.
    """
    n = len(arr)
    if n == 0:
        return 0

    # Calculate Longest Increasing Subsequence (LIS) ending at each index
    lis = [1] * n
    for i in range(1, n):
        for j in range(i):
            if arr[j] < arr[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Calculate Longest Decreasing Subsequence (LDS) starting at each index
    # This is equivalent to LIS on the reversed array from the right
    lds = [1] * n
    for i in range(n - 2, -1, -1):
        for j in range(n - 1, i, -1):
            if arr[j] < arr[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

