def capitalize_first_last_letters(s: str) -> str:
    words = s.split()
    result = []
    for word in words:
        if not word:
            continue
        if len(word) == 1:
            result.append(word.upper())
        else:
            first = word[0].upper()
            middle = word[1:-1].lower()
            last = word[-1].upper()
            result.append(first + middle + last)
    return ' '.join(result)
```

